const studentNames = `-- name: StudentNames :many
SELECT id, name, archived_at FROM students WHERE workspace_id = $1 AND id = ANY($2::uuid[])
`

type StudentNamesParams struct {
	WorkspaceID uuid.UUID
	Ids         []uuid.UUID
}

type StudentNamesRow struct {
	ID         uuid.UUID
	Name       string
	ArchivedAt *time.Time
}

// Names for billing, archived students included.
func (q *Queries) StudentNames(ctx context.Context, arg StudentNamesParams) ([]StudentNamesRow, error) {
	rows, err := q.db.Query(ctx, studentNames, arg.WorkspaceID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StudentNamesRow
	for rows.Next() {
		var i StudentNamesRow
		if err := rows.Scan(&i.ID, &i.Name, &i.ArchivedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const studentTaughtBy = `-- name: StudentTaughtBy :one
SELECT EXISTS (
    SELECT 1 FROM students s
    WHERE s.workspace_id = $1 AND s.id = $2
      AND (s.primary_teacher_membership_id = $3
           OR EXISTS (
               SELECT 1 FROM lesson_participants p
               JOIN lesson_tutors t ON t.lesson_id = p.lesson_id
               WHERE p.workspace_id = s.workspace_id AND p.student_id = s.id
                 AND t.membership_id = $3))
) AS taught
`

type StudentTaughtByParams struct {
	WorkspaceID  uuid.UUID
	StudentID    uuid.UUID
	MembershipID *uuid.UUID
}

// Whether the membership is the student's primary teacher or teaches them.
func (q *Queries) StudentTaughtBy(ctx context.Context, arg StudentTaughtByParams) (bool, error) {
	row := q.db.QueryRow(ctx, studentTaughtBy, arg.WorkspaceID, arg.StudentID, arg.MembershipID)
	var taught bool
	err := row.Scan(&taught)
	return taught, err
}

const studentsLinkedTo = `-- name: StudentsLinkedTo :many
SELECT DISTINCT s.id, s.name FROM students s
WHERE s.workspace_id = $1 AND s.archived_at IS NULL
  AND (s.user_id = $2 OR EXISTS (
       SELECT 1 FROM student_contacts c
       WHERE c.workspace_id = s.workspace_id AND c.student_id = s.id AND c.user_id = $2))
ORDER BY s.name, s.id
`

type StudentsLinkedToParams struct {
	WorkspaceID uuid.UUID
	UserID      *uuid.UUID
}

type StudentsLinkedToRow struct {
	ID   uuid.UUID
	Name string
}

// The students a person is linked to: as a contact (parent) or as the
// student.
func (q *Queries) StudentsLinkedTo(ctx context.Context, arg StudentsLinkedToParams) ([]StudentsLinkedToRow, error) {
	rows, err := q.db.Query(ctx, studentsLinkedTo, arg.WorkspaceID, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StudentsLinkedToRow
	for rows.Next() {
		var i StudentsLinkedToRow
		if err := rows.Scan(&i.ID, &i.Name); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

