const updateGoal = `-- name: UpdateGoal :one
UPDATE student_goals
SET title = COALESCE($1, title),
    status = COALESCE($2, status),
    achieved_at = CASE
        WHEN $2::goal_status = 'achieved' THEN COALESCE(achieved_at, $3)
        WHEN $2::goal_status IS NOT NULL THEN NULL
        ELSE achieved_at END,
    updated_at = now()
WHERE workspace_id = $4 AND student_id = $5 AND id = $6
RETURNING id, workspace_id, student_id, title, status, created_by_membership, achieved_at, created_at, updated_at
`

